using u128=unsigned __int128;
static std::string dec(u128 x){if(!x)return"0";std::string s;while(x){s.push_back('0'+x%10);x/=10;}std::reverse(s.begin(),s.end());return s;}
struct Row{std::array<uint8_t,6> id;uint64_t count;};
static int mi(int a,int b){if(a>b)std::swap(a,b);int k=0;for(int x=0;x<4;x++)for(int y=x;y<4;y++,k++)if(x==a&&y==b)return k;throw std::runtime_error("mi");}
static int id80(int e,int z){return e*40+(z&3)*10+mi((z>>2)&3,(z>>4)&3);}
static int id128(int e,int z){return e*64+z;}
static uint64_t enc(std::array<uint8_t,6>a){std::sort(a.begin(),a.end());uint64_t x=0;for(auto z:a)x=x*128+z;return x;}
static std::vector<Row> census(){std::vector<uint64_t> codes;codes.reserve(27ULL*64*64*64);for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int c=0;c<3;c++)for(int u=0;u<64;u++)for(int v=0;v<64;v++)for(int w=0;w<64;w++)codes.push_back(enc({(uint8_t)id128(a!=0,u),(uint8_t)id128(b!=0,v),(uint8_t)id128(c!=0,w),(uint8_t)id128(a!=b,u^v),(uint8_t)id128(a!=c,u^w),(uint8_t)id128(b!=c,v^w)}));std::sort(codes.begin(),codes.end());std::vector<Row> rows;for(size_t i=0;i<codes.size();){size_t j=i+1;while(j<codes.size()&&codes[j]==codes[i])j++;auto x=codes[i];Row r;r.count=j-i;for(int k=5;k>=0;k--){r.id[k]=x%128;x/=128;}rows.push_back(r);i=j;}return rows;}
static double fg(const std::vector<Row>&rs,const std::vector<double>&p,uint64_t mass,std::vector<double>*g=nullptr){if(g)std::fill(g->begin(),g->end(),0);long double f=0;for(auto&r:rs){long double a=1,b=1;for(auto q:r.id){a*=p[q];b*=1-p[q];}f+=r.count*(a+b);if(g)for(int i=0;i<6;i++){long double x=1,y=1;for(int j=0;j<6;j++)if(i!=j){x*=p[r.id[j]];y*=1-p[r.id[j]];}(*g)[r.id[i]]+=(double)((long double)r.count*(x-y)/mass);}}return(double)(f/mass);}
static double literal(const std::vector<double>&p){long double f=0;for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int c=0;c<3;c++)for(int u=0;u<64;u++)for(int v=0;v<64;v++)for(int w=0;w<64;w++){int q[6]={id128(a!=0,u),id128(b!=0,v),id128(c!=0,w),id128(a!=b,u^v),id128(a!=c,u^w),id128(b!=c,v^w)};long double x=1,y=1;for(int z:q){x*=p[z];y*=1-p[z];}f+=x+y;}return(double)(f/(27ULL*64*64*64));}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("usage report.json");constexpr int R=128,Q=65536;constexpr uint64_t MASS=27ULL*64*64*64;const int par[80]={0,61954,54732,58421,0,0,0,0,0,0,0,54732,61932,58343,0,0,0,0,0,0,0,54732,61932,58343,0,0,0,0,0,0,58276,0,0,0,51124,58356,54732,65536,61954,58343,65536,0,0,0,65536,65536,65536,65536,65536,65536,65536,0,0,0,65536,65536,65536,65536,65536,65536,65536,0,0,0,65536,65536,65536,65536,65536,65536,0,65536,65536,65536,0,0,0,0,0,0};auto rows=census();uint64_t hm=0;for(auto&r:rows)hm+=r.count;if(hm!=MASS)throw std::runtime_error("mass");std::vector<int>old(R),bm(R);std::vector<double>p(R);for(int e=0;e<2;e++)for(int z=0;z<64;z++){int j=id128(e,z);old[j]=id80(e,z);bm[j]=e?2:1;p[j]=(double)par[old[j]]/Q;}double base=fg(rows,p,MASS);if(fabs(base-.030140295686154409)>2e-14||fabs(literal(p)-base)>2e-14)throw std::runtime_error("parent/literal control");std::vector<double>pc(R);for(int j=0;j<R;j++)pc[j]=1-p[j];if(fabs(fg(rows,pc,MASS)-base)>2e-14)throw std::runtime_error("complement");
 std::vector<double>g(R),res(R);fg(rows,p,MASS,&g);double maxres=0,energy=0;int split=0;for(int o=0;o<80;o++){if(par[o]==0||par[o]==Q)continue;long double sw=0,sh=0;for(int j=0;j<R;j++)if(old[j]==o){sw+=bm[j];sh+=g[j];}double mean=(double)(sh/sw);for(int j=0;j<R;j++)if(old[j]==o){res[j]=g[j]/bm[j]-mean;maxres=std::max(maxres,fabs(res[j]));energy+=bm[j]*res[j]*res[j];split++;}}
 std::vector<std::vector<double>>H(R,std::vector<double>(R));for(auto&r:rows)for(int a=0;a<6;a++)for(int b=a+1;b<6;b++){long double x=1,y=1;for(int c=0;c<6;c++)if(c!=a&&c!=b){x*=p[r.id[c]];y*=1-p[r.id[c]];}double z=(double)((long double)r.count*(x+y)/MASS);int i=r.id[a],j=r.id[b];if(i==j)H[i][i]+=2*z;else H[i][j]+=z,H[j][i]+=z;}
 std::vector<std::vector<double>>B;for(int o=0;o<80;o++){if(par[o]==0||par[o]==Q)continue;std::vector<int>ch;for(int j=0;j<R;j++)if(old[j]==o)ch.push_back(j);if(ch.size()<2)continue;int ref=ch.back();for(size_t a=0;a+1<ch.size();a++){std::vector<double>v(R);v[ch[a]]=1;v[ref]=-(double)bm[ch[a]]/bm[ref];B.push_back(v);}}
 int D=B.size();std::vector<std::vector<double>>A(D,std::vector<double>(D)),V(D,std::vector<double>(D));for(int i=0;i<D;i++){V[i][i]=1;for(int j=0;j<D;j++)for(int a=0;a<R;a++)if(B[i][a])for(int b=0;b<R;b++)if(B[j][b])A[i][j]+=B[i][a]*H[a][b]*B[j][b];}auto A0=A;for(int it=0;it<100*std::max(1,D*D);it++){int u=0,v=0;double mx=0;for(int i=0;i<D;i++)for(int j=i+1;j<D;j++)if(fabs(A[i][j])>mx)mx=fabs(A[i][j]),u=i,v=j;if(mx<1e-18)break;double ph=.5*atan2(2*A[u][v],A[v][v]-A[u][u]),c=cos(ph),s=sin(ph);for(int k=0;k<D;k++){double x=A[k][u],y=A[k][v];A[k][u]=c*x-s*y;A[k][v]=s*x+c*y;}for(int k=0;k<D;k++){double x=A[u][k],y=A[v][k];A[u][k]=c*x-s*y;A[v][k]=s*x+c*y;}for(int k=0;k<D;k++){double x=V[k][u],y=V[k][v];V[k][u]=c*x-s*y;V[k][v]=s*x+c*y;}}
 double mineig=D?A[0][0]:0;int mini=0;for(int i=1;i<D;i++)if(A[i][i]<mineig)mineig=A[i][i],mini=i;double off=0,eigres=0;for(int i=0;i<D;i++)for(int j=0;j<D;j++)if(i!=j)off=std::max(off,fabs(A[i][j]));for(int i=0;i<D;i++){double z=-mineig*V[i][mini];for(int j=0;j<D;j++)z+=A0[i][j]*V[j][mini];eigres=std::max(eigres,fabs(z));}
 double best=base,hdelta=0;std::vector<double>bp=p;if(mineig<-1e-14){std::vector<double>d(R);for(int i=0;i<D;i++)for(int j=0;j<R;j++)d[j]+=B[i][j]*V[i][mini];double dm=0;for(double x:d)dm=std::max(dm,fabs(x));for(double&x:d)x/=dm;double cap=.1;for(int j=0;j<R;j++)if(d[j]>0)cap=std::min(cap,(1-p[j])/d[j]);else if(d[j]<0)cap=std::min(cap,-p[j]/d[j]);for(double st=.8*cap;st>1e-14;st*=.5){auto t=p;for(int j=0;j<R;j++)t[j]+=st*d[j];double f=fg(rows,t,MASS);if(f<best-1e-16){best=f;bp=t;hdelta=f-base;break;}}}
 // Continue only in old-mean-preserving directions.
 for(int it=0;it<300;it++){fg(rows,bp,MASS,&g);std::fill(res.begin(),res.end(),0);double mr=0;for(int o=0;o<80;o++){if(par[o]==0||par[o]==Q)continue;long double sw=0,sh=0;for(int j=0;j<R;j++)if(old[j]==o)sw+=bm[j],sh+=g[j];double mean=(double)(sh/sw);for(int j=0;j<R;j++)if(old[j]==o)res[j]=g[j]/bm[j]-mean,mr=std::max(mr,fabs(res[j]));}if(mr<1e-14)break;for(double&x:res)x/=-mr;double cap=.04;for(int j=0;j<R;j++)if(res[j]>0)cap=std::min(cap,(1-bp[j])/res[j]);else if(res[j]<0)cap=std::min(cap,-bp[j]/res[j]);bool moved=false;for(double st=.8*cap;st>1e-14;st*=.5){auto t=bp;for(int j=0;j<R;j++)t[j]+=st*res[j];double f=fg(rows,t,MASS);if(f<best-1e-16){best=f;bp=t;moved=true;break;}}if(!moved)break;}
 std::vector<uint64_t>rp(R);std::vector<double>rpd(R);for(int j=0;j<R;j++)rp[j]=llround(bp[j]*Q),rpd[j]=(double)rp[j]/Q;double rd=fg(rows,rpd,MASS);u128 exact=0;for(auto&r:rows){u128 a=1,b=1;for(auto id:r.id)a*=rp[id],b*=Q-rp[id];exact+=(u128)r.count*(a+b);}u128 den=MASS;for(int i=0;i<6;i++)den*=Q;
 std::ofstream out(argv[1]);out<<std::setprecision(17)<<"{\n \"schema\":\"quadratic-full-cayley-gate-v1\",\n \"status\":\"completed\",\n \"histogram_rows\":"<<rows.size()<<",\n \"controls\":\"matched 80-bin parent, literal translation, complement passed\",\n \"baseline\":"<<base<<",\n \"split_bins\":"<<split<<",\n \"initial_centered_gradient_max\":"<<maxres<<",\n \"initial_centered_gradient_energy\":"<<energy<<",\n \"hessian_dimension\":"<<D<<",\n \"hessian_min_eigenvalue_basis_coordinates\":"<<mineig<<",\n \"jacobi_terminal_offdiagonal_max\":"<<off<<",\n \"eigenpair_residual_inf\":"<<eigres<<",\n \"hessian_step_delta\":"<<hdelta<<",\n \"optimized_density\":"<<best<<",\n \"rationalized_density\":"<<rd<<",\n \"exact_numerator\":\""<<dec(exact)<<"\",\n \"exact_denominator\":\""<<dec(den)<<"\",\n \"beats_current_best\":"<<(rd<.03013890356539909?"true":"false")<<",\n \"rationalized_parameters\":[";for(int j=0;j<R;j++){if(j)out<<',';out<<rp[j];}out<<"]\n}\n";std::cout<<std::setprecision(17)<<"rows "<<rows.size()<<" base "<<base<<" grad "<<maxres<<" D "<<D<<" eig "<<mineig<<" residual "<<eigres<<" best "<<best<<" rational "<<rd<<"\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
